insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e01', 'c01', 's01', 'u-est1', '2026-08-19', 'validada', 'Sessão 1. Acolhimento e contrato terapêutico (horário, faltas, sigilo e seus limites). Paciente relata preocupação constante com o trabalho e dificuldade para dormir. Objetivo inicial combinado: compreender os gatilhos da ansiedade.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e02', 'c01', 's02', 'u-est2', '2026-08-26', 'validada', 'Sessão 2. Exploração das situações que disparam a ansiedade no trabalho. Introduzido registro diário de situações, pensamentos e reações.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e03', 'c01', 's04', 'u-est1', '2026-09-09', 'validada', 'Sessão 3. Revisão do registro diário: paciente identifica reuniões com a chefia como principal gatilho. Trabalhadas estratégias de respiração e preparação prévia para reuniões.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e14', 'c01', 's24', 'u-est2', '2026-09-23', 'validada', 'Sessão 4. Retomado o registro diário. Paciente percebe que a ansiedade aumenta nas reuniões de segunda-feira. Intervenção: psicoeducação sobre ansiedade e respiração diafragmática. Plano: praticar a respiração antes das reuniões.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e15', 'c01', 's25', 'u-est1', '2026-10-07', 'validada', 'Sessão 5. Paciente relata uso da respiração em duas reuniões, com alívio parcial. Trabalhada a relação entre pensamentos de cobrança e o sono. Plano: revisar os objetivos na próxima sessão.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e16', 'c01', 's27', 'u-est2', '2026-10-21', 'validada', 'Sessão 6. Revisão dos objetivos com a paciente: manter o foco no sono e incluir a comunicação com a chefia. Intervenção: ensaio de uma conversa difícil. Plano: observar situações de comunicação na semana.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e17', 'c01', 's28', 'u-est1', '2026-10-28', 'validada', 'Sessão 7. Paciente conversou com a chefia sobre prazos e relata menos preocupação à noite. Reforçadas as estratégias que funcionaram. Plano: acompanhar o padrão de sono.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e18', 'c01', 's29', 'u-est2', '2026-11-04', 'enviada', 'Sessão 8. Paciente relata duas noites de sono ruim depois de uma semana com muitas entregas. Trabalhada a antecipação de cenários negativos. Plano: registro de pensamentos nas noites difíceis.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e04', 'c01', null, 'u-est1', '2026-11-05', 'rascunho', 'Rascunho: planejar a revisão dos objetivos na próxima sessão.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e08', 'c02', 's06', 'u-est2', '2026-09-09', 'validada', 'Sessão 1. Acolhimento. Paciente relata isolamento após mudança de cidade. Combinado contrato e frequência semanal.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e19', 'c02', 's07', 'u-est1', '2026-09-23', 'validada', 'Sessão 2. Paciente fala da rotina na cidade nova e das poucas oportunidades de convívio. Mapeada a rede de apoio (colegas de trabalho e um primo). Plano: identificar um espaço de convivência para experimentar.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e20', 'c02', 's36', 'u-est2', '2026-10-07', 'validada', 'Sessão 3. Paciente visitou um grupo de caminhada e relata desconforto inicial e vontade de voltar. Trabalhadas expectativas sobre novas amizades. Plano: manter a participação semanal.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e21', 'c03', 's09', 'u-est3', '2026-08-26', 'validada', 'Sessão 1. Acolhimento e contrato terapêutico. Paciente relata sofrer com críticas de professores e colegas. Objetivo inicial: compreender como as críticas afetam a autoestima.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e22', 'c03', 's10', 'u-est4', '2026-09-02', 'validada', 'Sessão 2. Exploradas situações recentes de crítica e as reações da paciente. Intervenção: diferenciar crítica ao trabalho de crítica à pessoa. Plano: registrar uma situação da semana.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e23', 'c03', 's11', 'u-est3', '2026-09-16', 'validada', 'Sessão 3. Paciente trouxe o registro de uma apresentação em sala. Trabalhada comunicação assertiva com ensaio de respostas. Plano: experimentar uma resposta assertiva.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e24', 'c03', 's38', 'u-est4', '2026-09-30', 'validada', 'Sessão 4. Paciente relata ter pedido esclarecimento a um professor sem se desculpar em excesso. Reforçado o avanço. Plano: ampliar para situações com colegas.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e25', 'c03', 's39', 'u-est3', '2026-10-14', 'validada', 'Sessão 5. Trabalhada a autocrítica antes das provas. Intervenção: reestruturação de pensamentos de fracasso. Plano: preparar um plano de estudo realista.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e05', 'c03', 's41', 'u-est3', '2026-10-28', 'devolvida', 'Sessão 3. Paciente contou com muitos detalhes uma briga com a mãe, que gritou com ela na frente dos vizinhos e a chamou de fracassada.', 'Registre o tema e a intervenção, não o relato detalhado: o prontuário pode ser lido pela paciente. Ex.: "Trabalhado conflito familiar e o impacto na autoestima".', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e06', 'c04', 's13', 'u-est5', '2026-09-02', 'validada', 'Sessão 1 com o adolescente e o responsável. Contrato terapêutico e combinados sobre o sigilo: ao responsável será comunicado apenas o essencial para o cuidado.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e26', 'c04', 's14', 'u-est6', '2026-09-16', 'validada', 'Sessão 2 individual com o adolescente. Explorados interesses, rotina escolar e relações com os colegas. Plano: conhecer melhor a dinâmica familiar.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e27', 'c04', 's46', 'u-est7', '2026-09-30', 'validada', 'Sessão 3. Adolescente fala dos conflitos com o responsável sobre horários. Trabalhada a expressão de sentimentos sem agressividade. Plano: sessão de orientação ao responsável.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e28', 'c04', 's47', 'u-est5', '2026-10-14', 'validada', 'Sessão 4 com o responsável (orientação familiar), com a concordância do adolescente. Combinados horários e um momento semanal de conversa. Preservado o sigilo do conteúdo das sessões individuais.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e07', 'c04', 's48', 'u-est6', '2026-10-28', 'enviada', 'Sessão 5 individual. Adolescente relata menos brigas em casa e melhora na frequência escolar. Trabalhadas estratégias para as provas. Plano: revisar o combinado familiar.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e09', 'c05', 's16', 'u-est7', '2026-08-12', 'validada', 'Sessão 1. Acolhimento e contrato terapêutico. Paciente relata insegurança com a escolha profissional. Combinada frequência semanal às 11h.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e10', 'c06', 's19', 'u-est5', '2026-09-02', 'validada', 'Sessão 1. Acolhimento e contrato terapêutico. Paciente relata perda recente e dificuldade de retomar a rotina. Objetivo combinado: elaboração do luto.', '', 'sessao');
insert into evolucoes (id, caso_id, sessao_id, autor_id, data, status, texto, comentario_supervisor, tipo) values ('e11', 'c06', 's20', 'u-est6', '2026-09-09', 'validada', 'Sessão 2. Trabalhadas lembranças e sentimentos ligados à perda. Paciente identifica a rede de apoio familiar.', '', 'sessao');
