insert into planos_seguranca (id, caso_id, versao, autor_id, em, sinais_alerta, estrategias_proprias, pessoas_lugares, pessoas_ajuda, servicos, ambiente_seguro, razoes_viver, revisado_com_paciente) values ('ps01', 'c03', 1, 'u-est3', '2026-10-28T15:30', 'Passar mais de duas noites sem dormir; vontade de se isolar; pensar que é um peso para a família.', 'Caminhar no bairro; ouvir a lista de músicas que acalma; escrever no caderno o que está sentindo.', 'Ir à casa da irmã; ficar na praça perto de casa, onde há movimento.', 'A irmã e uma colega de trabalho de confiança (os telefones ficam no celular da paciente).', 'Clínica-escola, no horário de funcionamento; CVV 188 (24 horas); SAMU 192; UPA mais próxima.', 'Combinou deixar os medicamentos com a irmã e ficar só com os da semana.', 'A sobrinha; o curso que quer começar no ano que vem.', true);
